 function renderCatalog(){
  const items=courses.filter(c=>(category==='全部'||c.tag===category)&&(c.name+c.tag+c.summary).includes(query)),list=$('#openingList');list.replaceChildren();$('#openingCount').textContent=items.length+' / '+courses.length+' 课';$('#openingEmpty').hidden=!!items.length;$('#clearOpeningSearch').hidden=!!items.length;
  for(const c of items){const b=document.createElement('button');b.className='lesson-card'+(c===course?' active':'');b.setAttribute('aria-pressed',String(c===course));b.setAttribute('aria-label',c.name);const n=document.createElement('span');n.className='catalog-number';n.textContent=String(courses.indexOf(c)+1).padStart(2,'0');const info=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=c.name;const done=['r','b'].filter(side=>completed.has(c.id+':'+side)).length;small.textContent=c.level+' · 5回合'+(done?' · 跟练 '+done+'/2':'');info.append(strong,small);b.append(n,info);b.onclick=()=>{select(c);if(matchMedia('(max-width:760px)').matches)$('#openingDetail').scrollIntoView({behavior:'smooth',block:'start'})};list.append(b)}
 }
 function select(c){course=c;history.replaceState(null,'',location.pathname+location.search+'#'+c.id);line=XQStudy.build(E,{...course,pieces:initialPieces});$('#openingCategory').textContent=course.tag+' / '+course.level;$('#openingName').textContent=course.name;$('#openingSummary').textContent=course.summary;$('#openingPrinciple').textContent=course.principle;$('#openingPitfall').textContent=course.pitfall;$('#openingPlan').textContent=course.next;$('#openingIndex').textContent=(courses.indexOf(course)+1)+' / '+courses.length;$('#previousOpening').disabled=course===courses[0];$('#nextOpening').disabled=course===courses.at(-1);reset();renderCatalog()}
 function reset(){stop();ply=0;mode='demo';assisted=false;selected=null;targets=[];board=line.frames[0].slice();render();message('从完整开局开始。点击“下一手”看双方走法，或选择执子后开始跟练。')}
 function render(){renderBoard();renderPanel()}
